function art(type,extra=''){if(type==='box')return `<div class="product-art ${extra}"><div class="box-scene"><div class="gift-box"></div><div class="ribbon"></div></div><span class="placeholder">ILLUSTRATIVE PLACEHOLDER</span></div>`;if(type==='bag'||type==='envelope')return `<div class="product-art ${type} ${extra}"><span class="placeholder">ILLUSTRATIVE PLACEHOLDER</span></div>`;return `<div class="product-art ${extra}"><div class="paper-art ${type==='files'?'files':'books'}"><i></i><i></i><i></i></div><span class="placeholder">ILLUSTRATIVE PLACEHOLDER</span></div>`;}
