let filter='All',sub='All',boxStyle='All',jarCount='All',selected=null;
const main=['All','Office Products','School Products','Gifting','Diwali Finds'];const gifts=['All','Gift Boxes','Paper Bags','Paper Envelopes','Gift Wrappers'];
function isBox(p){return ['With Jar','Without Jar','Collapsible'].includes(p.category)}
function setFilter(f){filter=f;sub='All';boxStyle='All';jarCount='All';renderFilters();render();}
function renderFilters(){
 $('#filters').innerHTML=main.map(f=>`<button class="${filter===f?'active':''}" aria-pressed="${filter===f}" data-filter="${f}">${f}</button>`).join('');
 let list=(filter==='Gifting'||filter==='Diwali Finds')?gifts:filter==='Office Products'?['All','Filing and Organisation','Office Essentials','Other Paper Products']:filter==='School Products'?['All','School Essentials','Art Papers','Craft Papers']:['All','Gift Boxes','Paper Envelopes','Paper Bags','Gift Wrappers','Filing and Organisation','Office Essentials','Other Paper Products','School Essentials','Art Papers','Craft Papers'];
 $('#subfilters').innerHTML=list.map(f=>`<button class="${sub===f?'active':''}" aria-pressed="${sub===f}" data-sub="${f}">${f}</button>`).join('');
 $('#type-filter').innerHTML=list.map(f=>`<option value="${f}">${f==='All'?'All product types':f}</option>`).join('');$('#type-filter').value=sub;
 $('#jar-filter').value=jarCount;$('#jar-filter').disabled=filter==='School Products'||filter==='Office Products'||!['All','Gift Boxes'].includes(sub);
 $('#style-filter').value=boxStyle;$('#style-filter').disabled=filter==='School Products'||filter==='Office Products'||!['All','Gift Boxes'].includes(sub);
}
function selectType(value){sub=value;boxStyle='All';jarCount='All';renderFilters();render();}
if($('#products')){
$('#type-filter').onchange=e=>selectType(e.target.value);
$('#style-filter').onchange=e=>{boxStyle=e.target.value;jarCount='All';if(boxStyle!=='All'){sub='Gift Boxes';if(filter==='All')filter='Gifting';}renderFilters();render();};
$('#jar-filter').onchange=e=>{jarCount=e.target.value;if(jarCount!=='All'){sub='Gift Boxes';boxStyle=jarCount==='0'?'Without Jar':jarCount==='unspecified'?'All':'With Jar';if(filter==='All')filter='Gifting';}renderFilters();render();};
$('#clear-filters').onclick=()=>{$('#search').value='';setFilter('All');};
document.querySelectorAll('[data-diwali]').forEach(a=>a.onclick=()=>{filter='Diwali Finds';sub=a.dataset.diwali;boxStyle='All';jarCount='All';$('#search').value='';renderFilters();render();});
}
function render(){let q=$('#search').value.toLowerCase().trim();let list=products.filter(p=>(filter==='All'||p.group===filter||(filter==='Diwali Finds'&&p.group==='Gifting'))&&(sub==='All'||(sub==='Gift Boxes'?isBox(p):p.category===sub))&&(boxStyle==='All'||p.category===boxStyle)&&(jarCount==='All'||(isBox(p)&&(jarCount==='unspecified'?p.jarCount==null:p.jarCount===Number(jarCount))))&&q.split(/\s+/).every(word=>`${p.name} ${p.group} ${p.category} ${p.description} ${p.spec} ${p.group==='Gifting'?'diwali festive gifting':''}`.toLowerCase().includes(word)));$('#products').innerHTML=list.map(p=>`<article class="product-card">${productArt(p)}<p class="eyebrow">${p.group} / ${p.category}</p><h3><a href="#product/${p.id}" style="font-size:inherit;text-decoration:none">${p.name}</a></h3>${p.description?`<p>${p.description}</p>`:''}<div class="spec">${p.spec}</div><button data-product="${p.id}">Enquire / Request details <span style="float:right">${arrow}</span></button><a href="#product/${p.id}">WhatsApp enquiry ${arrow}</a></article>`).join('');$('#empty').hidden=list.length>0;$('#empty-message').textContent=jarCount==='3'?'No 3-jar box is listed in the current selected collection. Ask our team about available options.':'Try a different search, product type or jar count, or clear your filters.';$('#result-count').textContent=`${list.length} ${list.length===1?'product':'products'} found`;}
if($('#products')){
$('#filters').onclick=e=>{if(e.target.dataset.filter)setFilter(e.target.dataset.filter)};$('#subfilters').onclick=e=>{if(e.target.dataset.sub){selectType(e.target.dataset.sub);}};$('#search').oninput=render;
document.querySelectorAll('[data-select]').forEach(a=>a.onclick=()=>{boxStyle='All';let f=a.dataset.select;if(f==='Gift Boxes'){filter='Gifting';sub='Gift Boxes';renderFilters();render();}else setFilter(f);});
}
function openProduct(id){selected=products.find(p=>p.id===Number(id));if(!selected)return;$('#detail').innerHTML=productArt(selected)+`<p class="eyebrow">${selected.group} / ${selected.category}</p><h2>${selected.name}</h2>${selected.description?`<p>${selected.description}</p>`:''}<p class="spec">${selected.spec}</p><p class="spec">${selected.image?'Catalogue product photograph. Confirm current availability with our team.':'Illustrative placeholder. A photograph of this specific product will be added soon.'}</p>`;$('#product-form').reset();if(!$('#product-dialog').open)$('#product-dialog').showModal();}
function route(){if(location.hash.startsWith('#product/'))openProduct(location.hash.split('/')[1]);else if($('#product-dialog').open)$('#product-dialog').close();}
if($('#products'))$('#products').onclick=e=>{let b=e.target.closest('[data-product]');if(b)location.hash=`product/${b.dataset.product}`;};window.addEventListener('hashchange',route);function closeProduct(){$('#product-dialog').close();if(location.hash.startsWith('#product/'))history.replaceState(null,'','#catalogue');}$('.close').onclick=closeProduct;$('#product-dialog').addEventListener('cancel',e=>{e.preventDefault();closeProduct();});$('#product-dialog').onclick=e=>{if(e.target===$('#product-dialog')){const r=e.target.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)closeProduct();}};
function whatsapp(form,title){let msg=title+'\n\n'+[...new FormData(form)].map(([k,v])=>`${k}: ${v||'Not specified'}`).join('\n');window.open('https://wa.me/919867518902?text='+encodeURIComponent(msg),'_blank','noopener');}
$('#product-form').onsubmit=e=>{e.preventDefault();whatsapp(e.currentTarget,`Hello Oasis Bazaar, I would like to enquire about: ${selected.name}\nCategory: ${selected.category}`);};if($('#wholesale-form'))$('#wholesale-form').onsubmit=e=>{e.preventDefault();whatsapp(e.currentTarget,'Hello Oasis Bazaar, I have a wholesale enquiry.');};$('#year').textContent=new Date().getFullYear();if($('#products')){const params=new URLSearchParams(location.search);const page=location.pathname.split('/').pop().replace(/\.html$/,'');const categoryPage={school:'School Products',office:'Office Products',gifting:'Gifting',diwali:'Diwali Finds'};filter=categoryPage[page]||(main.includes(params.get('category'))?params.get('category'):'All');if(params.get('category')==='Gift Boxes'){filter='Gifting';sub='Gift Boxes';}const type=params.get('type');if(gifts.includes(type))sub=type;renderFilters();render();}route();

if($('#featured-products')){$('#featured-products').innerHTML=[products.find(p=>p.article==='574'),products.find(p=>p.name==='Paper Bag - Designer'),products.find(p=>p.name==='Sketch Book'),products.find(p=>p.name==='Executive Box File')].filter(Boolean).map(p=>`<article class="product-card">${productArt(p)}<p class="eyebrow">${p.group}</p><h3>${p.name}</h3><a class="text-link" href="catalogue.html#product/${p.id}">Request details ${arrow}</a></article>`).join('');}
if($('#video-form')){const d=new Date();const local=new Date(d.getTime()+330*60000).toISOString().slice(0,10);$('#call-date').min=local;$('#video-form').onsubmit=e=>{e.preventDefault();whatsapp(e.currentTarget,'Hello Oasis Bazaar, I would like to request a video call. Please confirm a suitable slot and share the call link.');};}
